/*
 RED GEEK 3D STUDIO
 Inteligência Comercial — Ploomes + n8n + Gemini

 - Consulta negócios ganhos
 - Usa Data do Pedido
 - Calcula faturamento, líquido e taxas
 - Analisa canais e meses
 - Separa produtos descritos como:
   5x Produto A;1x Produto B
 - Valida quantidades
 - Calcula projeção de 3 meses
 - Prepara prompt para Gemini
*/

const entradas = $input.all();

// Reúne negócios de todas as páginas da API
const negocios = entradas.flatMap(item => {
  const dados = item.json;

  if (Array.isArray(dados)) {
    return dados.flatMap(x =>
      Array.isArray(x.value) ? x.value : x.Id ? [x] : []
    );
  }

  if (Array.isArray(dados.value)) return dados.value;
  if (dados.Id) return [dados];

  return [];
});

// IDs dos campos da Red Geek no Ploomes
const F = {
  pedido: 40000420,
  canal: 40000421,
  situacao: 40000422,
  produto: 40000423,
  quantidade: 40000424,
  valorProdutos: 40000425,
  desconto: 40000426,
  freteCobrado: 40000427,
  outrasDespesas: 40000428,
  comissao: 40000429,
  bruto: 40000430,
  custoFrete: 40000431,
  taxas: 40000432,
  data: 40000446
};

function campo(deal, id) {
  const p = (deal.OtherProperties || [])
    .find(x => x.FieldId === id);

  if (!p) return null;

  return p.ObjectValueName ??
    p.DecimalValue ??
    p.IntegerValue ??
    p.DateTimeValue ??
    p.BigStringValue ??
    p.StringValue ??
    null;
}

function numero(valor) {
  if (valor == null || valor === "") return 0;

  const n = Number(valor);
  return Number.isFinite(n) ? n : 0;
}

function arred(valor) {
  return Math.round((valor + Number.EPSILON) * 100) / 100;
}

function somar(lista, chave) {
  return lista.reduce(
    (total, item) => total + numero(item[chave]), 0
  );
}

// Evita negócios duplicados entre páginas
const vistos = new Set();
const vendas = [];
let negociosSemData = 0;

for (const d of negocios) {
  if (d.StatusId !== 2) continue;
  if (vistos.has(d.Id)) continue;

  vistos.add(d.Id);

  const data = campo(d, F.data);

  if (!data) {
    negociosSemData++;
    continue;
  }

  const dataPedido = String(data).slice(0, 10);

  vendas.push({
    negocioId: d.Id,
    pedido: campo(d, F.pedido),
    data: dataPedido,
    mes: dataPedido.slice(0, 7),
    canal: campo(d, F.canal) || "Não informado",
    situacao: campo(d, F.situacao),
    produtoOriginal: campo(d, F.produto) || "",
    quantidade: numero(campo(d, F.quantidade)),
    bruto: numero(campo(d, F.bruto)),
    liquido: numero(d.Amount),
    taxas: numero(campo(d, F.taxas)),
    comissao: numero(campo(d, F.comissao)),
    custoFrete: numero(campo(d, F.custoFrete)),
    desconto: numero(campo(d, F.desconto)),
    freteCobrado: numero(campo(d, F.freteCobrado)),
    outrasDespesas: numero(campo(d, F.outrasDespesas))
  });
}

// =====================================
// 1. ANÁLISE MENSAL
// =====================================

const porMes = {};

for (const v of vendas) {
  if (!porMes[v.mes]) {
    porMes[v.mes] = {
      mes: v.mes,
      pedidos: 0,
      bruto: 0,
      liquido: 0,
      taxas: 0
    };
  }

  const m = porMes[v.mes];
  m.pedidos++;
  m.bruto += v.bruto;
  m.liquido += v.liquido;
  m.taxas += v.taxas;
}

const historicoMensal = Object.values(porMes)
  .map(m => ({
    mes: m.mes,
    pedidos: m.pedidos,
    bruto: arred(m.bruto),
    liquido: arred(m.liquido),
    taxas: arred(m.taxas),
    percentualTaxas: m.bruto > 0
      ? arred(m.taxas / m.bruto * 100)
      : 0
  }))
  .sort((a, b) => a.mes.localeCompare(b.mes));

// =====================================
// 2. ANÁLISE POR CANAL
// =====================================

const porCanal = {};

for (const v of vendas) {
  if (!porCanal[v.canal]) {
    porCanal[v.canal] = {
      canal: v.canal,
      pedidos: 0,
      bruto: 0,
      liquido: 0,
      taxas: 0,
      comissao: 0,
      custoFrete: 0
    };
  }

  const c = porCanal[v.canal];

  c.pedidos++;
  c.bruto += v.bruto;
  c.liquido += v.liquido;
  c.taxas += v.taxas;
  c.comissao += v.comissao;
  c.custoFrete += v.custoFrete;
}

const rankingCanais = Object.values(porCanal)
  .map(c => ({
    canal: c.canal,
    pedidos: c.pedidos,
    bruto: arred(c.bruto),
    liquido: arred(c.liquido),
    taxas: arred(c.taxas),
    comissao: arred(c.comissao),
    custoFrete: arred(c.custoFrete),
    percentualTaxas: c.bruto > 0
      ? arred(c.taxas / c.bruto * 100)
      : 0,
    ticketMedio: c.pedidos > 0
      ? arred(c.bruto / c.pedidos)
      : 0
  }))
  .sort((a, b) => b.bruto - a.bruto);

// =====================================
// 3. INTERPRETAÇÃO DOS PRODUTOS
// =====================================

const produtosAgrupados = new Map();
const pedidosDivergentes = [];

let pedidosProdutosValidados = 0;
let unidadesValidadas = 0;
let pedidosMultiplosProdutos = 0;

for (const v of vendas) {
  const texto = String(v.produtoOriginal).trim();

  // Separa os itens pelo ponto e vírgula
  const partes = texto.split(";")
    .map(p => p.trim())
    .filter(Boolean);

  const itens = partes.map(parte => {
    // Aceita 5x, 5X ou 5×
    const match = parte.match(
      /^(\d+)\s*[x×]\s*(.+)$/i
    );

    if (!match) return null;

    const quantidade = Number(match[1]);
    const nome = match[2].trim()
      .replace(/\s+/g, " ");

    if (!nome || quantidade <= 0) return null;

    return { nome, quantidade };
  });

  const totalInterpretado = itens.reduce(
    (total, item) => total + (item?.quantidade || 0),
    0
  );

  const valido =
    partes.length > 0 &&
    itens.every(item => item !== null) &&
    Number.isInteger(v.quantidade) &&
    totalInterpretado === v.quantidade;

  // Pedidos com erro não entram no ranking
  if (!valido) {
    pedidosDivergentes.push({
      pedido: v.pedido,
      negocioId: v.negocioId,
      quantidadePedido: v.quantidade,
      quantidadeInterpretada: totalInterpretado,
      descricao: texto || "Produto não informado"
    });

    continue;
  }

  pedidosProdutosValidados++;
  unidadesValidadas += totalInterpretado;

  if (itens.length > 1) {
    pedidosMultiplosProdutos++;
  }

  // Conta cada pedido uma vez por produto
  const produtosNoPedido = new Set();

  for (const item of itens) {
    const chave = item.nome.toLowerCase();

    if (!produtosAgrupados.has(chave)) {
      produtosAgrupados.set(chave, {
        produto: item.nome,
        quantidade: 0,
        pedidos: 0
      });
    }

    const registro = produtosAgrupados.get(chave);

    registro.quantidade += item.quantidade;

    if (!produtosNoPedido.has(chave)) {
      registro.pedidos++;
      produtosNoPedido.add(chave);
    }
  }
}

const rankingProdutos = [...produtosAgrupados.values()]
  .sort((a, b) =>
    b.quantidade - a.quantidade ||
    b.pedidos - a.pedidos
  );

const auditoriaProdutos = {
  pedidosValidados: pedidosProdutosValidados,
  pedidosDivergentes: pedidosDivergentes.length,
  pedidosComMultiplosProdutos: pedidosMultiplosProdutos,
  unidadesValidadas,
  produtosDistintos: rankingProdutos.length,
  exemplosDivergentes: pedidosDivergentes.slice(0, 20)
};

// =====================================
// 4. PROJEÇÃO DOS PRÓXIMOS 3 MESES
// =====================================

const mesAtual = new Intl.DateTimeFormat(
  "en-CA", {
    timeZone: "America/Sao_Paulo",
    year: "numeric",
    month: "2-digit"
  }
).format(new Date()).replace("/", "-");

const mesesCompletos = historicoMensal
  .filter(m => m.mes < mesAtual);

const ultimos3 = mesesCompletos.slice(-3);

let projecoes = [];
let metodoProjecao = "Dados históricos insuficientes";

if (ultimos3.length === 3) {
  const indices = ultimos3.map(m => {
    const [ano, mes] = m.mes.split("-").map(Number);
    return ano * 12 + mes;
  });

  const consecutivos =
    indices[1] === indices[0] + 1 &&
    indices[2] === indices[1] + 1;

  if (consecutivos) {
    const media = arred(
      somar(ultimos3, "bruto") / 3
    );

    metodoProjecao =
      "Média móvel simples dos últimos 3 meses completos";

    const [ano, mes] = ultimos3[2].mes
      .split("-").map(Number);

    for (let i = 1; i <= 3; i++) {
      const data = new Date(
        Date.UTC(ano, mes - 1 + i, 1)
      );

      projecoes.push({
        mes: data.toISOString().slice(0, 7),
        faturamentoPrevisto: media
      });
    }
  }
}

// =====================================
// 5. RESUMO EXECUTIVO
// =====================================

const faturamentoBruto = arred(somar(vendas, "bruto"));
const recebimentoLiquido = arred(somar(vendas, "liquido"));
const totalTaxas = arred(somar(vendas, "taxas"));

const relatorio = {
  dataGeracao: new Date().toISOString(),
  periodoInicial: historicoMensal[0]?.mes || null,
  periodoFinal:
    historicoMensal[historicoMensal.length - 1]?.mes || null,

  totalNegocios: vendas.length,
  negociosSemData,

  faturamentoBruto,
  recebimentoLiquido,
  totalTaxas,

  percentualTaxas: faturamentoBruto > 0
    ? arred(totalTaxas / faturamentoBruto * 100)
    : 0,

  ticketMedio: vendas.length > 0
    ? arred(faturamentoBruto / vendas.length)
    : 0,

  historicoMensal,
  rankingCanais,
  rankingProdutos,
  auditoriaProdutos,

  metodoProjecao,
  projecoes,

  avisos: [
    "A data oficial da venda é Data do Pedido.",
    "Recebimento líquido não representa lucro.",
    "Ainda faltam custos para calcular rentabilidade real.",
    "As quantidades do ranking de produtos foram validadas.",
    "Pedidos divergentes não entram no ranking de produtos.",
    "Não há faturamento individual confiável para produtos em pedidos mistos.",
    "Projeções são estimativas e não garantem vendas futuras."
  ]
};

// =====================================
// 6. PROMPT PARA O GEMINI
// =====================================

// Limita o tamanho do prompt sem perder
// os totais nem os indicadores principais
const dadosIA = {
  ...relatorio,
  rankingProdutos: rankingProdutos.slice(0, 30),
  auditoriaProdutos: {
    ...auditoriaProdutos,
    exemplosDivergentes:
      auditoriaProdutos.exemplosDivergentes.slice(0, 10)
  }
};

const promptIA = `
Você é um analista de inteligência comercial
da Red Geek 3D Studio.

Crie um relatório executivo profissional em português.

ESTRUTURA:

1. Resumo comercial do período.
2. Faturamento bruto e recebimento líquido.
3. Evolução mensal e tendências.
4. Comparação entre canais de venda.
5. Ranking dos produtos por unidades vendidas.
6. Projeções para os próximos 3 meses, se disponíveis.
7. Riscos, oportunidades e ações recomendadas.
8. Qualidade e limitações dos dados.

REGRAS OBRIGATÓRIAS:

- Utilize somente os dados fornecidos.
- Não invente faturamento, custos ou quantidades.
- Não confunda valor líquido com lucro.
- O ranking de produtos considera somente pedidos validados.
- A quantidade dos produtos foi extraída de textos
  como "5x Produto A;1x Produto B".
- Não atribua faturamento total de pedidos mistos
  a um único produto.
- Não afirme que um produto é mais lucrativo
  sem conhecer seu custo.
- Informe quantos pedidos tiveram divergências.
- A lista de produtos recebida contém no máximo
  os 30 primeiros do ranking.
- As projeções foram calculadas pelo n8n.
  Não altere os valores projetados.
- Diferencie fatos, hipóteses e recomendações.
- Considere o períodoInicial e periodoFinal,
  não invente um mês de referência.
- Seja objetivo, analítico e estratégico.

DADOS COMERCIAIS:
${JSON.stringify(dadosIA)}
`;

return [{
  json: {
    ...relatorio,
    promptIA
  }
}];

const indicadores = $('Calcular Indicadores Comerciais')
  .first().json;

const respostaGemini = $input.first().json;

const textoRelatorio =
  respostaGemini.content?.parts
    ?.map(parte => parte.text || "")
    .join("\n") || "";

if (!textoRelatorio.trim()) {
  throw new Error("O Gemini não retornou um relatório.");
}

return [{
  json: {
    dataGeracao: indicadores.dataGeracao,
    periodoInicial: indicadores.periodoInicial,
    periodoFinal: indicadores.periodoFinal,

    totalNegocios: indicadores.totalNegocios,
    faturamentoBruto: indicadores.faturamentoBruto,
    recebimentoLiquido: indicadores.recebimentoLiquido,
    totalTaxas: indicadores.totalTaxas,
    percentualTaxas: indicadores.percentualTaxas,
    ticketMedio: indicadores.ticketMedio,

    historicoMensal: indicadores.historicoMensal,
    rankingCanais: indicadores.rankingCanais,
    rankingProdutos: indicadores.rankingProdutos,
    auditoriaProdutos: indicadores.auditoriaProdutos,
    projecoes: indicadores.projecoes,

    relatorioIA: textoRelatorio,
    status: "GERADO"
  }
}];

const relatorio = $('Preparar Relatorio Executivo')
  .first().json;

const historico = relatorio.historicoMensal || [];

return historico.map(mes => ({
  json: {
    mes: mes.mes,
    pedidos: Number(mes.pedidos),
    bruto: Number(mes.bruto),
    liquido: Number(mes.liquido),
    taxas: Number(mes.taxas),
    percentualTaxas: Number(mes.percentualTaxas)
  }
}));

const relatorio = $('Preparar Relatorio Executivo')
  .first().json;

const produtos = relatorio.rankingProdutos || [];

return produtos.map(p => ({
  json: {
    produto: p.produto,
    quantidade: Number(p.quantidade),
    pedidos: Number(p.pedidos)
  }
}));

const relatorio = $('Preparar Relatorio Executivo')
  .first().json;

const canais = relatorio.rankingCanais || [];

return canais.map(c => ({
  json: {
    canal: c.canal,
    pedidos: Number(c.pedidos),
    bruto: Number(c.bruto),
    liquido: Number(c.liquido),
    taxas: Number(c.taxas),
    comissao: Number(c.comissao),
    custoFrete: Number(c.custoFrete),
    percentualTaxas: Number(c.percentualTaxas),
    ticketMedio: Number(c.ticketMedio)
  }
}));

const r = $('Preparar Relatorio Executivo').first().json;

const moeda = v => Number(v || 0).toLocaleString('pt-BR', {
  style: 'currency',
  currency: 'BRL'
});

const seguro = v => String(v ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const meses = r.historicoMensal || [];
const canais = r.rankingCanais || [];
const produtos = (r.rankingProdutos || []).slice(0, 30);
const projecoes = r.projecoes || [];

// Serialização segura para inserir dados dentro do HTML
const dados = JSON.stringify({
  meses,
  canais,
  produtos,
  projecoes,
  relatorio: r.relatorioIA || ''
})
.replace(/</g, '\\u003c')
.replace(/>/g, '\\u003e')
.replace(/&/g, '\\u0026')
.replace(/\u2028/g, '\\u2028')
.replace(/\u2029/g, '\\u2029');

const linhasCanais = canais.map(c => `
<tr>
<td>${seguro(c.canal)}</td>
<td>${moeda(c.bruto)}</td>
<td>${moeda(c.liquido)}</td>
<td>${Number(c.percentualTaxas).toFixed(2).replace('.', ',')}%</td>
</tr>`).join('');

const linhasProdutos = produtos.map(p => `
<tr>
<td>${seguro(p.produto)}</td>
<td>${Number(p.quantidade)}</td>
<td>${Number(p.pedidos)}</td>
</tr>`).join('');

const linhasProjecoes = projecoes.map(p => `
<div class="previsao">
<span>${seguro(p.mes)}</span>
<strong>${moeda(p.faturamentoPrevisto)}</strong>
</div>`).join('');

const html = `<!DOCTYPE html>
