<body>
<main>

<h1>RED GEEK 3D STUDIO</h1>
<p class="sub">
Dashboard de Inteligência Comercial |
${seguro(r.periodoInicial)} a ${seguro(r.periodoFinal)}
</p>

<div class="filtros">
  <div class="filtro">
    <label for="mesInicio">Mês inicial</label>
    <input type="month" id="mesInicio"
      value="${seguro(r.periodoInicial)}">
  </div>

  <div class="filtro">
    <label for="mesFim">Mês final</label>
    <input type="month" id="mesFim"
      value="${seguro(r.periodoFinal)}">
  </div>

