  'pt-BR',
  {style:'currency',currency:'BRL'}
);

const percentual = n =>
  Number(n || 0).toFixed(2).replace('.', ',') + '%';

let graficoVendas = null;

function aplicarFiltro() {
  const inicio = document.getElementById('mesInicio').value;
  const fim = document.getElementById('mesFim').value;
  const aviso = document.getElementById('avisoFiltro');

  if (inicio && fim && inicio > fim) {
    aviso.textContent = 'O mês inicial deve ser anterior ao mês final.';
    return;
  }

  const filtrados = dados.meses.filter(m =>
    (!inicio || m.mes >= inicio) &&
    (!fim || m.mes <= fim)
  );

  const somar = campo =>
    filtrados.reduce((total,m) => total + Number(m[campo] || 0),0);

  const bruto = somar('bruto');
  const liquido = somar('liquido');
  const pedidos = somar('pedidos');
  const taxas = somar('taxas');

  document.getElementById('cardBruto').textContent = formatoBRL(bruto);
  document.getElementById('cardLiquido').textContent = formatoBRL(liquido);
  document.getElementById('cardPedidos').textContent = pedidos;
  document.getElementById('cardTaxas').textContent =
    percentual(bruto > 0 ? taxas / bruto * 100 : 0);

  aviso.textContent = filtrados.length
    ? 'Indicadores mensais atualizados para o período selecionado.'
    : 'Nenhum mês com vendas no período selecionado.';

  if (graficoVendas) {
    graficoVendas.data.labels = filtrados.map(x => x.mes);
    graficoVendas.data.datasets[0].data = filtrados.map(x => x.bruto);
    graficoVendas.data.datasets[1].data = filtrados.map(x => x.liquido);
    graficoVendas.update();
  }
}

document.getElementById('mesInicio')
  .addEventListener('change', aplicarFiltro);

document.getElementById('mesFim')
  .addEventListener('change', aplicarFiltro);

document.getElementById('limparFiltro')
  .addEventListener('click', () => {
    document.getElementById('mesInicio').value =
      dados.meses[0]?.mes || '';
    document.getElementById('mesFim').value =
      dados.meses[dados.meses.length - 1]?.mes || '';
    aplicarFiltro();
  });

