for (const item of (analise.recomendacoes || [])) {
  const produto = String(item.produto || "").trim();
  const classe = String(
    item.classificacao || ""
  ).toUpperCase();

  const confianca = String(
    item.confianca || "BAIXA"
  ).toUpperCase();

  if (!classes.includes(classe)) {
    recomendacoesRevisao.push({
      produto,
      motivo: "Classificação inválida"
    });
    continue;
  }

  // Evita produtos criados ou agrupados pela IA
  if (!produtosReais.has(produto)) {
    recomendacoesRevisao.push({
      produto,
      motivo: "Produto não encontrado no ranking original"
    });
    continue;
